await mkdir(new URL("../apps/web/src/locales/", import.meta.url), {
  recursive: true,
});
for (const [language, translations] of Object.entries(data)) {
  const resource = {};
  for (const [group, keys] of Object.entries(groups)) {
    const values = translations[group].split("|");
    if (values.length !== keys.length)
      throw new Error(
        `${language}/${group}: expected ${keys.length}, received ${values.length}`,
      );
    keys.forEach((key, index) => {
      if (!values[index]) throw new Error(`${language}: empty ${key}`);
      resource[key] = values[index];
    });
  }
  await writeFile(
    new URL(`../apps/web/src/locales/${language}.json`, import.meta.url),
    JSON.stringify(resource, null, 2) + "\n",
  );
}
console.log(
  `Generated ${Object.keys(data).length} complete locales (${Object.values(groups).flat().length} keys each).`,
);
await import("./alliance-locales.mjs");
